      <el-pagination :current-page="videoPage" :page-size="20" :total="videoCount" layout="total, prev, pager, next" @current-change="loadVideos" />
    </el-dialog>
    <ProductVideoUploader v-if="videoUploadOpen && canUploadMedia" :key="mediaSession.key" :open="videoUploadOpen" :disabled="!canEdit" :context-key="mediaSession.key" subject-label="页面" @update:open="videoUploadOpen = $event" @use="mediaSession.chooseVideo" />
  </section>
</template>

<script setup lang="ts">
