function commit(value: unknown[]): boolean { if (!editableNow()) return false; try { const raw = JSON.stringify(value, null, 2); presentationDocument(raw); emit('update:modelValue', raw); return true; } catch (reason) { error.value = reason instanceof Error ? reason.message : '内容不能保存'; return false; } }
function edit(change: (row: PresentationRecord) => void): boolean { if (!canEdit.value || !block.value || !kind.value || !documentValue.value) return false; const value = structuredClone(documentValue.value), row = record(value[selectedIndex.value]); if (!row) return false; change(row); return commit(value); }
