function moveComponent(direction: number) { if (!documentValue.value || ![-1, 1].includes(direction)) return; const neighbour = entries.value[selectedPosition.value + direction]; if (!neighbour) return; const from = selectedIndex.value, to = neighbour.index, value = structuredClone(documentValue.value), a = record(value[from])!, b = record(value[to])!; const ah = Object.hasOwn(a, 'timestamp'), bh = Object.hasOwn(b, 'timestamp'), at = a.timestamp, bt = b.timestamp; if (bh) a.timestamp = bt; else delete a.timestamp; if (ah) b.timestamp = at; else delete b.timestamp; [value[from], value[to]] = [value[to], value[from]]; if (commit(value)) selectedIndex.value = to; }
