const enumFields = computed(() => kind.value === 'titles' ? [{ key: 'buttonConfig', label: '更多按钮', fallback: 0, options: ['显示', '隐藏'] }, { key: 'textPosition', label: '标题位置（更多按钮隐藏时）', fallback: 0, options: ['左对齐', '居中', '右对齐'] }, { key: 'textStyle', label: '文字样式', fallback: 0, options: ['正常', '斜体', '粗体'] }] : kind.value === 'guide' ? [{ key: 'lineStyle', label: '线条样式', fallback: 1, options: ['虚线', '实线', '点状线'] }] : kind.value === 'videos' ? [{ key: 'scaleConfig', label: '视频比例', fallback: 0, options: ['16:9', '4:3', '1:1'] }] : []);
const textFields = computed(() => kind.value === 'titles' ? [{ key: 'titleConfig', label: '标题文字', max: 10 }, { key: 'titleConfigRight', label: '更多文字', max: 5 }, { key: 'linkConfig', label: '跳转链接', max: 100 }] : []);
const colourFields = computed(() => { const f = (key: string, label: string, fallback: string, index = 0) => ({ key, label, fallback, index }); if (kind.value === 'titles') return [f('themeColor', '标题颜色', '#333333'), f('buttonColor', '更多文字颜色', '#999999'), f('titleColor', '渐变起始色', '#ffffff'), f('titleColor', '渐变结束色', '#ffffff', 1), f('bottomBgColor', '外层背景', '#fff')]; if (kind.value === 'guide') return [f('lineColor', '线条颜色', '#f5f5f5'), f('lineBgColor', '外层背景', '#E93323')]; return [...(kind.value === 'blankPage' || kind.value === 'richText' ? [f('bgColor', '内容背景', '#ffffff')] : []), f('bottomBgColor', '外层背景', kind.value === 'videos' ? '#F5F5F5' : '#E93323')]; });
const lengthFields = computed(() => { const f = (key: string, label: string, fallback = 0, min = 0) => ({ key, label, fallback, min }); return [f('topConfig', '上内边距', kind.value === 'guide' ? 6 : 0), f('bottomConfig', '下内边距', kind.value === 'guide' ? 6 : 0), f(kind.value === 'richText' ? 'lrConfig' : kind.value === 'guide' || kind.value === 'blankPage' ? 'lrEdge' : 'prConfig', '左右内边距'), ...(kind.value === 'blankPage' ? [f('heightConfig', '空白高度', 10, 1)] : [f(kind.value === 'richText' ? 'udConfig' : 'mbConfig', '页面上间距')]), ...(kind.value === 'titles' ? [f('fontSize', '标题字号', 16, 8), f('buttonText', '更多字号', 12, 6)] : [])]; });
function tab(key: string, fallback: number) { const value = record(block.value?.[key])?.tabVal, max = enumFields.value.find(field => field.key === key)?.options.length ?? 0; return (typeof value === 'number' && Number.isInteger(value) || typeof value === 'string' && /^[0-2]$/u.test(value)) && Number(value) >= 0 && Number(value) < max ? Number(value) : fallback; }
