function setReference(key: string, value: unknown): boolean { if (kind.value !== 'videos' || !['videoConfig', 'imgConfig'].includes(key) || typeof value !== 'string') return false; const reference = canonicalPresentationReference(value.trim()); if (reference && !/^(?:https:\/\/|\/(?!\/))/iu.test(reference) || /[\u0000-\u0020\u007f\x5c]/u.test(reference)) { error.value = '请输入稳定 HTTPS 或站内素材地址'; return false; } if (reference.length > 4096) { error.value = '素材地址不能超过4096字符'; return false; } return edit(row => { row[key] = { ...record(row[key]), url: reference }; }); }
function remember(reference: string, preview: string) { const approved = presentationPreviewForReference(reference, preview); if (approved) previews.value = { ...previews.value, [canonicalPresentationReference(reference)]: approved }; }
function applyMedia(type: 'image' | 'video', reference: string, preview: string, issued: string) { if (!current(issued) || !canChooseMedia.value || !['richText', 'videos'].includes(kind.value ?? '')) return; const canonical = canonicalPresentationReference(reference); if (!canonical || canonical.length > 4096 || !/^(?:https:\/\/|\/(?!\/))/iu.test(canonical) || /[\u0000-\u0020\u007f\x5c]/u.test(canonical)) return; let applied: boolean; if (kind.value === 'videos') applied = setReference(type === 'image' ? 'imgConfig' : 'videoConfig', canonical); else { const escaped = canonical.replaceAll('&', '&amp;').replaceAll('"', '&quot;').replaceAll('<', '&lt;').replaceAll('>', '&gt;'); applied = setHtml(html.value + (type === 'image' ? `<p><img src="${escaped}" /></p>` : `<p><video src="${escaped}" controls></video></p>`)); } if (applied) remember(canonical, preview); }
const mediaSession = computed(() => { const issued = stamp(); return { key: `${props.editorKey}:${revision.value}:${selectedIndex.value}`, chooseImage: (reference: string, preview: string) => applyMedia('image', reference, preview, issued), chooseVideo: (value: { url: string; src: string }) => applyMedia('video', value.url, value.src, issued) }; });
function mediaPreview(key: string) { const reference = mediaReference(key); return presentationPreviewForReference(reference, previews.value[canonicalPresentationReference(reference)] ?? reference); }
function preventPreviewLink(event: MouseEvent) { const target = event.target as { closest?: (selector: string) => Element | null } | null; if (typeof target?.closest === 'function' && target.closest('a')) event.preventDefault(); }
const previewHtml = computed(() => { try { return mapDiyPresentationHtmlMedia(sanitizeDiyPresentationHtml(html.value), reference => presentationPreviewForReference(reference, previews.value[canonicalPresentationReference(reference)] ?? reference)); } catch { return ''; } });
async function openVideoLibrary() { if (!canChooseMedia.value || !['richText', 'videos'].includes(kind.value ?? '')) return; closeVideoLibrary(); videoLibraryOpen.value = true; libraryStamp = stamp(); videoName.value = ''; videoPid.value = 0; const issued = libraryStamp, controller = new AbortController(); categoryAbort = controller; try { const data = await apiAttachmentCategories(controller.signal, { all: true, file_type: 2 }); if (!current(issued) || !videoLibraryOpen.value) return; if (!data || !Array.isArray(data.list) || data.list.some(row => !row || !Number.isSafeInteger(row.id) || row.id < 1 || typeof row.name !== 'string')) throw Error('视频分类响应格式错误'); videoCategories.value = data.list; } catch (reason) { if (current(issued)) videoCategoryError.value = reason instanceof Error ? reason.message : '视频分类读取失败'; } finally { if (categoryAbort === controller) categoryAbort = null; } if (current(issued)) await loadVideos(1); }
async function loadVideos(page: number) { if (!videoLibraryOpen.value || !current(libraryStamp) || !canChooseMedia.value || !Number.isSafeInteger(page) || page < 1 || page > 501) return; libraryAbort?.abort(); const controller = new AbortController(), issued = libraryStamp, serial = ++libraryRequest; libraryAbort = controller; videoLoading.value = true; videoError.value = ''; videos.value = []; videoPage.value = page;
  try { const data = await apiAttachmentList({ file_type: 2, page, limit: 20, pid: videoPid.value, name: videoName.value.trim() }, controller.signal); if (!current(issued) || !videoLibraryOpen.value || serial !== libraryRequest || !canChooseMedia.value) return; if (!data || !Array.isArray(data.list) || data.list.length > 20 || !Number.isSafeInteger(data.count) || data.count < 0 || data.list.some(row => !row || !Number.isSafeInteger(row.att_id) || row.att_id < 1 || row.file_type !== 2 || typeof row.canonical_url !== 'string' || typeof row.att_dir !== 'string' || typeof row.real_name !== 'string' || !presentationPreviewForReference(row.canonical_url, row.att_dir) || row.canonical_url.startsWith('/api/assets/') && row.canonical_url !== `/api/assets/${row.att_id}`)) throw Error('视频库响应格式错误'); videos.value = data.list; videoCount.value = data.count;
  } catch (reason) { if (current(issued) && serial === libraryRequest) videoError.value = reason instanceof Error ? reason.message : '视频库读取失败'; } finally { if (libraryAbort === controller) { videoLoading.value = false; libraryAbort = null; } }
}
function chooseVideo(item: AttachmentItem) { const actual = videos.value.find(row => row.att_id === item.att_id && row.canonical_url === item.canonical_url); if (!actual || !current(libraryStamp) || !canChooseMedia.value || videoLoading.value || !videoLibraryOpen.value) return; applyMedia('video', actual.canonical_url, actual.att_dir, libraryStamp); closeVideoLibrary(); }
function comparable(value: PresentationRecord) { const copy = canonicalPresentationBlock(value), rich = record(copy.richText); if (copy.name === 'richText' && typeof rich?.val === 'string') rich.val = sanitizeDiyPresentationHtml(rich.val); return JSON.stringify(copy); }
async function loadSavedPreviews() { if (!canEdit.value || !block.value || !props.pageId || !props.pagePublished || !['richText', 'videos'].includes(kind.value ?? '')) return; cancelPreview(); const controller = new AbortController(), issued = stamp(), id = props.pageId; previewAbort = controller; previewLoading.value = true; error.value = '';
  try { const expected = comparable(block.value); const response = await fetch(`/api/diy/get_diy/${id}`, { credentials: 'omit', cache: 'no-store', signal: controller.signal }); const body = record(await response.json()), data = record(body?.data); if (!response.ok || body?.status !== 200 || !Array.isArray(data?.value)) throw Error('公开素材预览暂不可用，请核对发布状态或素材库'); if (!current(issued) || !props.pagePublished || props.pageId !== id || controller.signal.aborted) return; const found = data.value.map(record).find(row => row && presentationKind(row.name) === kind.value && comparable(row) === expected); if (!found) throw Error('当前内容与已保存的公开配置不一致；请保存后读取或从素材库选择'); const next: Record<string, string> = {}; if (kind.value === 'videos') for (const key of ['videoConfig', 'imgConfig']) { const value = record(found[key])?.url; if (typeof value === 'string' && safePreview(value)) next[canonicalPresentationReference(value)] = value; } else { const value = record(found.richText)?.val; if (typeof value === 'string') mapDiyPresentationHtmlMedia(value, reference => { if (safePreview(reference)) next[canonicalPresentationReference(reference)] = reference; return reference; }); } previews.value = next;
  } catch (reason) { if (current(issued)) error.value = reason instanceof Error ? reason.message : '公开预览读取失败'; } finally { if (previewAbort === controller) { previewAbort = null; previewLoading.value = false; } }
}
const radiusStyle = computed(() => block.value ? presentationRadius(block.value) : '0');
const wrapperStyle = computed<CSSProperties>(() => ({ padding: `${length('topConfig')}px ${length(kind.value === 'richText' ? 'lrConfig' : kind.value === 'guide' || kind.value === 'blankPage' ? 'lrEdge' : 'prConfig')}px ${length('bottomConfig')}px`, marginTop: kind.value === 'blankPage' ? '0' : `${length(kind.value === 'richText' ? 'udConfig' : 'mbConfig')}px`, background: colour(kind.value === 'guide' ? 'lineBgColor' : 'bottomBgColor', 0, kind.value === 'titles' ? '#fff' : kind.value === 'videos' ? '#F5F5F5' : '#E93323') }));
const titleBoxStyle = computed<CSSProperties>(() => ({ borderRadius: radiusStyle.value, background: `linear-gradient(90deg,${colour('titleColor', 0, '#ffffff')},${colour('titleColor', 1, '#ffffff')})`, justifyContent: tab('buttonConfig', 0) ? ['flex-start', 'center', 'flex-end'][tab('textPosition', 0)] : 'space-between' }));
const titleTextStyle = computed<CSSProperties>(() => ({ fontSize: `${length('fontSize', 16)}px`, color: colour('themeColor', 0, '#333333'), fontStyle: tab('textStyle', 0) === 1 ? 'italic' : 'normal', fontWeight: tab('textStyle', 0) === 2 ? 'bold' : 'normal' }));
const moreStyle = computed<CSSProperties>(() => ({ fontSize: `${length('buttonText', 12)}px`, color: colour('buttonColor', 0, '#999999') }));
const blankStyle = computed<CSSProperties>(() => ({ height: `${length('heightConfig', 10)}px`, background: colour('bgColor', 0, '#f5f5f5'), borderRadius: radiusStyle.value }));
const guideStyle = computed<CSSProperties>(() => ({ borderBottom: `0.5px ${['dashed', 'solid', 'dotted'][tab('lineStyle', 1)]} ${colour('lineColor', 0, '#f5f5f5')}` }));
const richStyle = computed<CSSProperties>(() => ({ padding: '15px', background: colour('bgColor', 0, '#ffffff'), borderRadius: radiusStyle.value }));
const videoStyle = computed<CSSProperties>(() => ({ aspectRatio: ['16 / 9', '4 / 3', '1 / 1'][tab('scaleConfig', 0)], borderRadius: radiusStyle.value }));
</script>

